{"project": "Boltons", "base_commit": "979fa9b613fa8c0a455ae16ea6f2ec91c11ecafe", "problem": "Removing values leaves internal dead slots. IndexedSet slicing then mixes physical storage offsets with visible item positions and returns incorrect contents. Slicing must depend on the visible ordered contents rather than mutation history.", "expected_behavior": "Positive-step slices must match slicing the visible list, including negative bounds and out-of-range bounds. Preserve the established Boltons negative-step convention: normalize negative bounds against visible length, reverse the stream, then apply forward bounds and absolute step (not Python list negative-step semantics). Preserve IndexedSet return type, scalar indexing, item order, length, and nonmutation by slicing.", "allowed_paths": ["boltons/setutils.py"], "files": {"boltons/__init__.py": {"lines": 1, "sha256": "bc65b003e91e1580b6deb48f9c11fc5702756f7acaeeed894dabcb02873bc452"}, "boltons/setutils.py": {"lines": 969, "sha256": "6dc3c91b2c3bc30d319d62803a5ba1ac326022fce7b24e3402d455c897f3c478"}, "tests/test_setutils.py": {"lines": 205, "sha256": "fcc144f552fd19e91949d8b0b5bc0d46e6e74971f22081a0b6e317bee077abfe"}, "LICENSE": {"lines": 29, "sha256": "c301912653a8d8c99eab6212aa3aea8d164ea249d8ad53c941e0558a0a5ac1e3"}}, "ordinary_command": ["python", "-m", "pytest", "-q", "-p", "no:cacheprovider", "tests/test_setutils.py"], "environment": "Python 3.12.14, pytest 8.3.5; no network; read-only source; fixed installed dependencies", "source_excerpts": [{"path": "boltons/setutils.py", "symbol": "IndexedSet._get_real_index", "start": 158, "end": 168, "content": "    def _get_real_index(self, index):
        if index < 0:
            index += len(self)
        if not self.dead_indices:
            return index
        real_index = index
        for d_start, d_stop in self.dead_indices:
            if real_index < d_start:
                break
            real_index += d_stop - d_start
        return real_index
"}, {"path": "boltons/setutils.py", "symbol": "IndexedSet.remove", "start": 240, "end": 248, "content": "    def remove(self, item):
        "remove(item) -> remove item from the set, raises if not present"
        try:
            didx = self.item_index_map.pop(item)
        except KeyError:
            raise KeyError(item)
        self.item_list[didx] = _MISSING
        self._add_dead(didx)
        self._cull()
"}, {"path": "boltons/setutils.py", "symbol": "IndexedSet.iter_slice", "start": 392, "end": 402, "content": "    def iter_slice(self, start, stop, step=None):
        "iterate over a slice of the set"
        iterable = self
        if start is not None:
            start = self._get_real_index(start)
        if stop is not None:
            stop = self._get_real_index(stop)
        if step is not None and step < 0:
            step = -step
            iterable = reversed(self)
        return islice(iterable, start, stop, step)
"}, {"path": "boltons/setutils.py", "symbol": "IndexedSet.__getitem__", "start": 405, "end": 420, "content": "    def __getitem__(self, index):
        try:
            start, stop, step = index.start, index.stop, index.step
        except AttributeError:
            index = operator.index(index)
        else:
            iter_slice = self.iter_slice(start, stop, step)
            return self.from_iterable(iter_slice)
        if index < 0:
            index += len(self)
        real_index = self._get_real_index(index)
        try:
            ret = self.item_list[real_index]
        except IndexError:
            raise IndexError('IndexedSet index out of range')
        return ret
